#include "closed_transpose_arithmetic.hpp"
struct CMEncoded {Class value;std::vector<int> auxiliary;std::array<int,3> overlap{};};
struct CMAdapter {
    QuarticKM& km;EBPoly f;std::vector<int> reference;std::array<std::vector<CFPoly>,3> jets;
    CMAdapter(QuarticKM& k,EBPoly ff,const Json& formal):km(k),f(std::move(ff)){
        for(auto& i:formal.at("seed_indices").arr)reference.push_back(i.integer());require(reference.size()==3,"complete KM reference triple");CFPoly t{Z(0),Z(1)};std::vector<Z> modc(13,Z(0));modc[12]=Z(1);CFPoly modulus(modc);
        for(int r=0;r<3;++r){auto& p=km.points[size_t(reference[size_t(r)])];CFPoly x{Z(p.x)},y{p.y};bool xlocal=f.partial(1).eval(Z(p.x),p.y)!=Z(0);if(xlocal)x=x+t;else{require(f.partial(0).eval(Z(p.x),p.y)!=Z(0),"complete KM smooth reference chart");y=y+t;}auto derivative=f.partial(xlocal?1:0);for(int precision=1;precision<12;precision*=2){auto error=cm_curve(f,modulus,x,y),d=cm_curve(derivative,modulus,x,y);if(xlocal)y=(y-error*cm_inverse(d,modulus))%modulus;else x=(x-error*cm_inverse(d,modulus))%modulus;}require(cm_curve(f,modulus,x,y).degree()<0,"complete KM exact reference jets");for(auto e:km.mons)jets[size_t(r)].push_back((pc_power_mod(x,e[0],modulus)*pc_power_mod(y,e[1],modulus))%modulus);}
    }
    CMEncoded encode(const MCycle& c,int d){
        require(d>=1&&d<=3&&c.u.degree()==3*d,"complete KM cycle/source degree");require(cm_curve(f,c.u,c.x,c.y).degree()<0,"complete KM input cycle incidence");CMEncoded out;std::set<int> excluded(km.pool.begin(),km.pool.end());excluded.insert(reference.begin(),reference.end());for(int i=int(km.points.size())-1;i>=0&&out.auxiliary.size()<3;--i){auto& p=km.points[size_t(i)];if(!excluded.count(i)&&p.x!=km.fibers[0].x&&c.u.eval(Z(p.x)+Z(c.coordinate)*p.y)!=Z(0))out.auxiliary.push_back(i);}require(out.auxiliary.size()==3,"complete KM available auxiliary3");
        Space constraints(size_t(c.u.degree()),Vector(km.mons.size(),Z(0)));for(size_t j=0;j<km.mons.size();++j){auto e=km.mons[j];auto value=(pc_power_mod(c.x,e[0],c.u)*pc_power_mod(c.y,e[1],c.u))%c.u;for(int i=0;i<c.u.degree();++i)constraints[size_t(i)][j]=value.at(i);}
        for(int r=0;r<3;++r){auto& p=km.points[size_t(reference[size_t(r)])];Z z=Z(p.x)+Z(c.coordinate)*p.y;CFPoly reduced=c.u;int m=0;while(reduced.degree()>0&&reduced.eval(z)==Z(0)){reduced=reduced.exact(CFPoly{-z,Z(1)});++m;}if(m)require(c.x.eval(z)==Z(p.x)&&c.y.eval(z)==p.y,"complete KM overlapping reference coordinate");out.overlap[size_t(r)]=m;for(int order=m;order<m+3-d;++order){require(order<12,"complete KM reference jet capacity");Vector row;for(auto& jet:jets[size_t(r)])row.push_back(jet.at(order));constraints.push_back(row);}}
        for(int i:out.auxiliary){auto& p=km.points[size_t(i)];Vector row;for(auto e:km.mons)row.push_back(zpow(Z(p.x),e[0])*zpow(p.y,e[1]));constraints.push_back(row);}require(constraints.size()==12,"complete KM effective degree12 constraints");auto coeff=nullspace(constraints,int(km.mons.size()));require(coeff.size()==22,"complete KM RR dimension22");Space values;for(auto& row:coeff)values.push_back(linear_combination(row,km.v3));Class positive{row_basis(values,evaluation_count)};require(positive.w.size()==22,"complete KM evaluation dimension22");std::map<int,int> baseline;for(int i:reference)baseline[i]=3;for(int i:out.auxiliary)++baseline[i];out.value=km.add(positive,km.negate(km.effective(baseline)));return out;
    }
};
int main(int argc,char** argv){try{
    require(argc==5,"usage: complete_km study global bridge formal");std::string root=argv[1];initialize_cover(read_json(root+"/inputs/p192-d7-prym.json"));Level2Input input;auto global=read_json(argv[2]),bridge=read_json(argv[3]),formal=read_json(argv[4]),model=read_json(root+"/evidence/p192-d7-kernel3-plane-quartic.json"),points=read_json(root+"/evidence/destination-relations-v2/result.json");EBPoly f;for(auto& row:model.at("terms").arr){auto e=row.at("exponents");f.add({e.arr[0].integer(),e.arr[1].integer()},Z(mpz_class(row.at("coefficient").scalar)));}MMap map(global,f);CFPoly x{Z(0),Z(1)},power=x;for(int d=1;d<=3;++d){power=powmod(power,prime,map.den);require(cf_gcd(map.den,power-x).degree()==0,"complete KM no reduced-source denominator poles");}QuarticKM km(model,points);CMAdapter adapter(km,f,formal);std::vector<G> source{G{},G{P{F(1)/(F(2)*cc),F(1)},P{}}};for(auto& row:bridge.at("images").arr)source.push_back(cm_source(row));std::vector<Class> classes{km.identity};std::vector<CMEncoded> encoded;
    for(size_t i=1;i<source.size();++i){auto image=map.forward(source[i]);require(image.shift<0&&image.e.degree()<=3,"complete KM rational source direct chart");auto out=adapter.encode(image.cycle,image.e.degree());classes.push_back(out.value);encoded.push_back(out);if(i>=2)require(km.equal(out.value,gb_class(bridge.at("images").arr[i-2].at("class_space"),km)),"complete KM pinned regular image");std::cerr<<"complete KM source fixture "<<i<<" passed\n";}require(km.zero(km.add(classes[1],classes[1])),"complete KM second branch order2");require(km.zero(km.add(classes[4],classes[5])),"complete KM source negation");require(km.equal(km.add(classes[4],classes[4]),classes[6]),"complete KM source doubling");require(km.equal(km.add(classes[4],classes[2]),classes[7]),"complete KM generic plus pullG");
    Class refclass=km.identity;for(int i:adapter.reference)refclass=km.add(refclass,km.point_class(i));auto nref=km.negate(refclass);GBSource::modulus=CFPoly{Z(0),Z(1)};auto& q=km.points[size_t(adapter.reference[0])];MAlgebra repeated(1,GBP{GBSource(0),GBSource(0),GBSource(0),GBSource(1)},GBP{GBSource(CFPoly{Z(q.x)})},GBP{GBSource(CFPoly{q.y})});auto repcycle=repeated.cycle(f);auto rep=adapter.encode(repcycle,1);require(rep.overlap[0]==3,"complete KM triple reference overlap");auto repexpected=km.add(pc_times(km,km.point_class(adapter.reference[0]),3),nref);require(km.equal(rep.value,repexpected),"complete KM order5 reference padding equality");
    auto& fiber=km.fibers[0].support;GBP u{GBSource(1)};for(int i=0;i<3;++i)u=u*GBP{GBSource(CFPoly{-km.points[size_t(fiber[size_t(i)])].y}),GBSource(1)};MAlgebra vertical(1,u,GBP{GBSource(CFPoly{Z(km.fibers[0].x)})},GBP{GBSource(0),GBSource(1)});auto collision=vertical.cycle(f);require(collision.coordinate>0,"complete KM collision uses alternate coordinate");auto col=adapter.encode(collision,1);Class expected=km.identity;for(int i=0;i<3;++i)expected=km.add(expected,km.point_class(fiber[size_t(i)]));expected=km.add(expected,nref);require(km.equal(col.value,expected),"complete KM alternate-coordinate rational comparison");
    std::cout<<"{\"scope\":\"P192-complete-forward-KM-interface\",\"standing\":\"producer-unverified\",\"actual_source_fixtures\":8,\"regular_pinned_comparisons\":6,\"branch_order2\":true,\"negation\":true,\"doubling\":true,\"addition\":true,\"collision_coordinate\":"<<collision.coordinate<<",\"reference_overlap_multiplicity\":"<<rep.overlap[0]<<",\"combined_reference_multiplicity\":"<<rep.overlap[0]+2<<",\"target_addflips\":"<<km.flips<<",\"class_spaces\":[";for(size_t i=0;i<classes.size();++i){if(i)std::cout<<',';pc_emit_class(classes[i]);}std::cout<<"],\"auxiliaries\":[";for(size_t i=0;i<encoded.size();++i){if(i)std::cout<<',';std::cout<<'[';for(size_t j=0;j<encoded[i].auxiliary.size();++j)std::cout<<(j?",":"")<<encoded[i].auxiliary[j];std::cout<<']';}std::cout<<"],\"overlap_control\":";pc_emit_class(rep.value);std::cout<<",\"collision_control\":";pc_emit_class(col.value);std::cout<<"}\n";
}catch(const std::exception& e){std::cerr<<"REJECT "<<e.what()<<'\n';return 1;}}
